import {COLLECTIONS,COLLECTION_ITEMS,inventoryState,collectionQuote} from './collections.js';
import {UNITS,BUILDINGS} from './catalog.js';
const sources={0:'Derrotar tropas enemigas',1:'Destruir edificios enemigos',3:'Ayudar a amigos · pausado',4:'Recolectar recursos'};
const rarities=['Poco común','Rara','Épica'];
function token(s,id,esc){const item=COLLECTION_ITEMS[id],n=inventoryState(s).items[id]||0;return'<li class="collection-token '+(n?'owned':'missing')+'" title="'+esc(sources[item.source]+' · '+rarities[item.rarity])+'"><span class="collectible-art" style="background-position:-'+((id-1)%5*60)+'px -'+(Math.floor((id-1)/5)*60)+'px" aria-hidden="true"></span><strong>'+esc(item.name)+'</strong><small>'+n+' / 1 · '+rarities[item.rarity]+'</small></li>';}
export function inventoryPanel(s,section,h){
 const {head,esc,img}=h,v=inventoryState(s),count=Object.values(v.items).reduce((n,q)=>n+q,0),ready=COLLECTIONS.filter(c=>collectionQuote(s,c.id).ok).length;
 const tabs='<div class="inventory-tabs" role="group" aria-label="Secciones del inventario">'+[['collections','Colecciones'+(ready?' · '+ready:'')],['items','Objetos · '+count],['storage','Almacén · '+v.storage.length]].map(([id,label])=>'<button data-action="inventory" data-type="'+id+'" aria-pressed="'+(section===id)+'" class="'+(section===id?'primary':'')+'">'+label+'</button>').join('')+'</div>';
 let content='';
 if(section==='items')content='<p>Las piezas se guardan al recogerlas. Una colección consume una pieza de cada tipo; los duplicados se conservan.</p>'+(count?'<ul class="inventory-items">'+Object.keys(v.items).map(Number).sort((a,b)=>a-b).map(id=>token(s,id,esc)).join('')+'</ul>':'<div class="inventory-empty"><h3>Tu inventario está vacío</h3><p>Combate y recoge recursos para encontrar piezas. Consulta en Colecciones dónde aparece cada una.</p></div>');
 else if(section==='storage')content='<p>Los premios esperan aquí hasta que decidas usarlos. Las tropas necesitan plazas libres; los edificios necesitan terreno despejado.</p>'+(v.storage.length?'<div class="stored-rewards">'+v.storage.map(id=>{const c=COLLECTIONS.find(c=>c.id===id),r=c.reward,spec=r.unit?UNITS[r.type]:BUILDINGS[r.type];return'<article class="stored-reward">'+img(r.type,r.level,r.unit)+'<div><small>COLECCIÓN '+esc(c.name.toUpperCase())+'</small><h3>'+esc(spec.name)+'</h3><p>'+(r.unit?spec.pop+' plazas de ejército':spec.size+' × '+spec.size+' casillas · nivel '+r.level)+'</p><button class="primary" data-action="stored-use" data-index="'+id+'">'+(r.unit?'Incorporar a la base':'Colocar en el mapa')+'</button></div></article>';}).join('')+'</div>':'<div class="inventory-empty"><h3>Sin recompensas pendientes</h3><p>Completa una colección y reclama su premio para guardarlo aquí.</p></div>');
 else content='<p>Reúne cinco piezas distintas y reclama el premio una vez por colección. Derrotar tropas o destruir edificios enemigos tiene un 8% de probabilidad de pieza. Cada 100 recursos realmente recolectados ofrece una tirada del 20%.</p><div class="collection-list">'+COLLECTIONS.map(c=>{const q=collectionQuote(s,c.id),r=c.reward,spec=r.unit?UNITS[r.type]:BUILDINGS[r.type];return'<article class="collection-card '+(q.done?'completed':'')+'"><header><h3>'+esc(c.name)+'</h3><span>'+ (q.done?'Completada':q.count+' / 5')+'</span></header><div class="collection-body"><div><p class="collection-source">'+esc(sources[COLLECTION_ITEMS[c.items[0]].source])+'</p><ul class="collection-pieces">'+c.items.map(id=>token(s,id,esc)).join('')+'</ul></div><div class="collection-reward"><small>RECOMPENSA</small>'+img(r.type,r.level,r.unit)+'<strong>'+esc(spec.name)+'</strong><button class="'+(q.ok?'primary':'')+'" data-action="collection-claim" data-index="'+c.id+'" '+(!q.ok?'disabled':'')+'>'+(q.done?'Reclamada':c.social?'Pausada':'Reclamar premio')+'</button></div></div></article>';}).join('')+'</div>';
 return head('OBJETOS Y RECOMPENSAS','Inventario')+tabs+'<div class="inventory-content">'+content+'</div>';
}
